import{_ as o,o as s,c as n,a3 as l}from"./chunks/framework.Cc-oPviL.js";const c=JSON.parse('{"title":"02 · 月度自测卷（30 题）","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/summary/02.md","filePath":"bagu/summary/02.md"}'),i={name:"bagu/summary/02.md"};function r(a,t,g,e,p,u){return s(),n("div",null,[...t[0]||(t[0]=[l(`<h1 id="_02-·-月度自测卷-30-题" tabindex="-1">02 · 月度自测卷（30 题） <a class="header-anchor" href="#_02-·-月度自测卷-30-题" aria-label="Permalink to &quot;02 · 月度自测卷（30 题）&quot;">​</a></h1><blockquote><p><strong>闭卷。不翻资料。限时 60 分钟。</strong> 目的不是打分，是找出&quot;以为懂了其实没懂&quot;的地方。</p></blockquote><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 先做题，把答案写在纸上（不要只在脑子里过，写出来才算）</span></span>
<span class="line"><span>② 做完再对答案，每题的&quot;评分标准&quot;告诉你答到哪算对</span></span>
<span class="line"><span>③ 统计错题，回到对应篇目重读</span></span>
<span class="line"><span>④ 一周后只重做错题</span></span></code></pre></div><p><strong>评分标准</strong>（每题按&quot;答到几层&quot;给分）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 分：答不出，或者完全说错</span></span>
<span class="line"><span>1 分：只答出&quot;是什么&quot;（第一层）</span></span>
<span class="line"><span>2 分：能答出&quot;为什么这样设计&quot;（第二层）</span></span>
<span class="line"><span>3 分：能答出&quot;不这样会怎么坏&quot;（第三层）</span></span></code></pre></div><hr><h2 id="第一部分-·-操作系统-1-8-题" tabindex="-1">第一部分 · 操作系统（1-8 题） <a class="header-anchor" href="#第一部分-·-操作系统-1-8-题" aria-label="Permalink to &quot;第一部分 · 操作系统（1-8 题）&quot;">​</a></h2><p><strong>1. 进程和线程的本质区别是什么？为什么线程切换比进程切换便宜？</strong></p><p><strong>2. 画出进程的 5 个状态，并说明&quot;阻塞能否直接转到运行&quot;，为什么？</strong></p><p><strong>3. 虚拟内存解决了哪三个具体问题？各举一个&quot;不这么做会出的事故&quot;。</strong></p><p><strong>4. 缺页中断的完整处理流程是什么？（至少 4 步）</strong></p><p><strong>5. 死锁的四个必要条件是什么？最实用的破坏手段是哪个？</strong></p><p><strong>6. 自旋锁和互斥锁分别适合什么场景？为什么单核 CPU 上不该用自旋锁？</strong></p><p><strong>7. 为什么说前四种 IO 模型都是&quot;同步 IO&quot;？</strong></p><p><strong>8. epoll 比 select 快在哪三点？什么情况下 epoll 不一定更快？</strong></p><hr><h2 id="第二部分-·-计算机网络-9-16-题" tabindex="-1">第二部分 · 计算机网络（9-16 题） <a class="header-anchor" href="#第二部分-·-计算机网络-9-16-题" aria-label="Permalink to &quot;第二部分 · 计算机网络（9-16 题）&quot;">​</a></h2><p><strong>9. 三次握手的过程？为什么不是两次？（要举出一个具体会出事的场景）</strong></p><p><strong>10. 四次挥手为什么是四次？什么情况下会变成三次？</strong></p><p><strong>11. TIME_WAIT 为什么必须等 2MSL？两个理由分别是什么？</strong></p><p><strong>12. 流量控制和拥塞控制的区别？分别用什么实现？</strong></p><p><strong>13. 超时重传和快速重传的处理有什么不同？为什么要区别对待？</strong></p><p><strong>14. TCP 队头阻塞是什么？HTTP/2 为什么解决不了？HTTP/3 怎么解决的？</strong></p><p><strong>15. 强缓存和协商缓存的区别？<code>no-cache</code> 和 <code>no-store</code> 有什么不同？</strong></p><p><strong>16. HTTPS 为什么要&quot;非对称 + 对称&quot;混用？证书解决的是什么问题？</strong></p><hr><h2 id="第三部分-·-数据结构与算法-17-23-题" tabindex="-1">第三部分 · 数据结构与算法（17-23 题） <a class="header-anchor" href="#第三部分-·-数据结构与算法-17-23-题" aria-label="Permalink to &quot;第三部分 · 数据结构与算法（17-23 题）&quot;">​</a></h2><p><strong>17. 数组和链表都是 O(n) 遍历，为什么实测差 10 倍？</strong></p><p><strong>18. 哈希表的 O(1) 是平均还是最坏？装太满会怎样？</strong></p><p><strong>19. 为什么数据库索引用 B+ 树，而不是哈希、红黑树、B 树？（四个都要说）</strong></p><p><strong>20. 堆为什么用数组存？建堆为什么是 O(n) 而不是 O(n log n)？</strong></p><p><strong>21. 为什么无权图的最短路用 BFS，而不是 DFS？</strong></p><p><strong>22. 并查集的两个优化是什么？为什么优化后接近 O(1)？</strong></p><p><strong>23. 快排最坏是 O(n²)，什么时候会发生？怎么避免？</strong></p><hr><h2 id="第四部分-·-数据库-24-30-题" tabindex="-1">第四部分 · 数据库（24-30 题） <a class="header-anchor" href="#第四部分-·-数据库-24-30-题" aria-label="Permalink to &quot;第四部分 · 数据库（24-30 题）&quot;">​</a></h2><p><strong>24. 2000 万行的表，B+ 树大概几层？一次查询几次磁盘 IO？（要能算出过程）</strong></p><p><strong>25. 什么是回表？什么是覆盖索引？</strong></p><p><strong>26. 联合索引 (a,b,c)，<code>WHERE a &gt; 1 AND b = 2</code> 能用到 b 吗？为什么？</strong></p><p><strong>27. ACID 分别由什么机制实现？为什么说&quot;C 不是数据库实现的&quot;？</strong></p><p><strong>28. redo log 和 binlog 的四个区别？为什么需要两阶段提交？</strong></p><p><strong>29. MVCC 靠哪三样东西实现？RC 和 RR 的唯一区别是什么？</strong></p><p><strong>30. 一条 SQL 很慢，你的排查顺序是什么？（至少 5 步）</strong></p><hr><hr><h1 id="答案与评分标准" tabindex="-1">答案与评分标准 <a class="header-anchor" href="#答案与评分标准" aria-label="Permalink to &quot;答案与评分标准&quot;">​</a></h1><blockquote><p><strong>先做完再看。</strong></p></blockquote><h2 id="第一部分-·-操作系统" tabindex="-1">第一部分 · 操作系统 <a class="header-anchor" href="#第一部分-·-操作系统" aria-label="Permalink to &quot;第一部分 · 操作系统&quot;">​</a></h2><p><strong>1. 进程和线程的区别</strong></p><ul><li>1 分：进程是资源分配单位，线程是调度单位；线程共享地址空间。</li><li>2 分：+ 线程独占栈和寄存器，共享堆和代码段。</li><li>3 分：+ <strong>切换成本的差别在页表</strong>——进程切换要换 CR3、导致 TLB 失效，线程共享页表不用换。</li><li><strong>命门</strong>：能不能说到 TLB。</li></ul><p><strong>2. 进程 5 状态</strong></p><ul><li>状态：新建、就绪、运行、阻塞、终止。</li><li><strong>阻塞不能直接到运行</strong>：因为 CPU 可能被别的进程占着，事件到达只是&quot;具备运行条件&quot;，还要重新排队等调度。</li><li>3 分：+ 能说清&quot;运行&gt;就绪&quot;是被动（时间片），&quot;运行&gt;阻塞&quot;是主动（发起 IO）。</li><li><strong>命门</strong>：&quot;阻塞 &gt; 就绪 &gt; 运行&quot;这条路径。</li></ul><p><strong>3. 虚拟内存的三个价值</strong></p><ul><li>① 隔离：每个进程独立地址空间，不会互相踩。</li><li>② 超卖：虚拟总量可以超过物理内存，按需调页。</li><li>③ 免连续：物理页可以散落，不需要连续的大块内存。</li><li>3 分：每个都能举出&quot;不这么做会出的事故&quot;。</li><li><strong>命门</strong>：三个都要说，只说&quot;扩大内存&quot;是 0 分。</li></ul><p><strong>4. 缺页中断流程</strong></p><ul><li>① 找空闲页框（没有就按置换算法选一个牺牲页）</li><li>② 牺牲页脏了先写回磁盘</li><li>③ 从磁盘/文件读入需要的页</li><li>④ 更新页表（存在位=1，填物理页号）</li><li>⑤ 重新执行触发缺页的那条指令</li><li>3 分：+ 能说清&quot;哪些是硬件做的、哪些是内核做的&quot;。</li><li><strong>命门</strong>：第 ⑤ 步&quot;重新执行&quot;不能漏。</li></ul><p><strong>5. 死锁四条件</strong></p><ul><li>互斥、持有并等待、不可剥夺、循环等待。</li><li><strong>最实用</strong>：破坏循环等待——所有资源按全局顺序申请。</li><li>3 分：+ 能解释&quot;为什么按顺序申请就不会有环&quot;。</li><li><strong>命门</strong>：说清&quot;破坏哪个&quot;比背四条重要。</li></ul><p><strong>6. 自旋锁 vs 互斥锁</strong></p><ul><li>临界区极短 + 多核 &gt; 自旋（省内核切换）；可能阻塞 &gt; 互斥。</li><li><strong>单核不能用自旋</strong>：占着唯一的核空转，持有锁的线程没机会运行来释放锁。</li><li>3 分：+ 提到&quot;读写锁适合读多写少&quot;。</li><li><strong>命门</strong>：&quot;单核为什么不行&quot;这半句。</li></ul><p><strong>7. 前四种都是同步 IO</strong></p><ul><li>因为<strong>第二阶段（内核缓冲区 &gt; 用户缓冲区）都是阻塞的</strong>，都要自己等拷贝完成。</li><li>只有 AIO 第二阶段也不阻塞。</li><li><strong>命门</strong>：判据是&quot;第二阶段谁完成、完不完成通知你&quot;。</li></ul><p><strong>8. epoll 快的三点</strong></p><ul><li>① 不用每次全量拷贝 fd 集合（注册一次）</li><li>② 不用遍历（回调把就绪的挂到链表）</li><li>③ 只返回就绪的 fd</li><li><strong>不一定更快</strong>：fd 少且全活跃时，select 遍历开销小，epoll 的回调注册反而是额外成本。</li><li><strong>命门</strong>：能说出&quot;什么时候 epoll 不占优&quot;。</li></ul><h2 id="第二部分-·-计算机网络" tabindex="-1">第二部分 · 计算机网络 <a class="header-anchor" href="#第二部分-·-计算机网络" aria-label="Permalink to &quot;第二部分 · 计算机网络&quot;">​</a></h2><p><strong>9. 三次握手</strong></p><ul><li>SYN(seq=x) &gt; SYN+ACK(seq=y, ack=x+1) &gt; ACK(ack=y+1)。</li><li><strong>为什么不是两次</strong>：如果只有两次，服务器收到一个<strong>延迟到达的历史 SYN</strong> 就会立刻认为连接建立、分配资源；而客户端根本不认这个连接，会回 RST 或忽略 &gt; 服务器白占资源。三次握手的第三次让服务器确认&quot;客户端真的收到了我的 SYN&quot;。</li><li>3 分：+ 提到&quot;第三次可以带数据，前两次不能&quot;。</li><li><strong>命门</strong>：历史 SYN 这个场景要讲完整。</li></ul><p><strong>10. 四次挥手</strong></p><ul><li>因为全双工，两个方向要独立关闭。服务器收到 FIN 时<strong>可能还有数据没发完</strong>，所以 ACK 和 FIN 不能合并。</li><li><strong>变成三次</strong>：服务器确实没数据了，ACK+FIN 合并发送（延迟确认）。</li><li><strong>命门</strong>：&quot;还有数据要发&quot;这个理由。</li></ul><p><strong>11. TIME_WAIT 两个理由</strong></p><ul><li>① 保证最后一个 ACK 能到达（丢了对方会重发 FIN，还能再回 ACK）</li><li>② 让旧连接的残留报文在网络中消亡，避免污染使用相同四元组的新连接</li><li><strong>为什么 2MSL</strong>：覆盖&quot;我的 ACK 到对方&quot;+&quot;对方的 FIN 到我&quot;一个完整往返。</li><li><strong>命门</strong>：两个理由都要说。</li></ul><p><strong>12. 流量控制 vs 拥塞控制</strong></p><ul><li>流量控制：<strong>端到端</strong>，接收方通告窗口，防止发送方淹没接收方。用<strong>滑动窗口</strong>。</li><li>拥塞控制：<strong>全局</strong>，发送方推测网络拥堵，防止压垮网络。用 <strong>cwnd</strong>。</li><li>实际窗口 = min(rwnd, cwnd)。</li><li><strong>命门</strong>：&quot;一个怕对方收不下，一个怕路上堵&quot;。</li></ul><p><strong>13. 超时 vs 快速重传</strong></p><ul><li>超时：连 ACK 都没回来 &gt; 判断严重拥塞 &gt; cwnd 降到 1，重新慢启动。</li><li>快速重传：3 个重复 ACK &gt; 个别丢包 &gt; cwnd 减半，快速恢复。</li><li><strong>为什么区别对待</strong>：一个是&quot;路断了&quot;，一个是&quot;掉了个包裹&quot;。</li><li><strong>命门</strong>：这个类比要能说出来。</li></ul><p><strong>14. TCP 队头阻塞</strong></p><ul><li>TCP 保证按序交付，前面一段丢了，后面到的也要等。</li><li>HTTP/2 的多路复用是在<strong>同一条 TCP 连接</strong>上做，TCP 层丢包会卡住所有流——<strong>反而更糟</strong>。</li><li>HTTP/3 用 QUIC（UDP），每流独立排序和重传。</li><li><strong>命门</strong>：区分&quot;应用层 HOL&quot;和&quot;TCP 层 HOL&quot;。</li></ul><p><strong>15. 强缓存 vs 协商缓存</strong></p><ul><li>强缓存：<code>Cache-Control: max-age</code>，<strong>不发请求</strong>，直接用本地。</li><li>协商缓存：<code>If-None-Match</code> / <code>If-Modified-Since</code>，<strong>要发请求</strong>，没变回 304（不带 body）。</li><li><strong>no-cache</strong>：可以缓存，但每次必须校验（不是&quot;不缓存&quot;）。</li><li><strong>no-store</strong>：完全禁止缓存。</li><li><strong>命门</strong>：no-cache 的陷阱。</li></ul><p><strong>16. HTTPS 混合加密</strong></p><ul><li>非对称（RSA/ECDHE）安全但慢，只用来<strong>协商会话密钥</strong>；对称（AES）快，用来传数据。</li><li><strong>证书解决的问题</strong>：确认&quot;这个公钥确实属于这个域名&quot;，靠 CA 签名 + 证书链逐级验证到浏览器内置的根证书。</li><li>3 分：+ 提到&quot;用户信任了恶意根证书时 HTTPS 也防不住&quot;。</li><li><strong>命门</strong>：证书解决的是&quot;公钥归属&quot;。</li></ul><h2 id="第三部分-·-数据结构与算法" tabindex="-1">第三部分 · 数据结构与算法 <a class="header-anchor" href="#第三部分-·-数据结构与算法" aria-label="Permalink to &quot;第三部分 · 数据结构与算法&quot;">​</a></h2><p><strong>17. 数组比链表快 10 倍</strong></p><ul><li>CPU 按<strong>缓存行</strong>（64 字节）读内存。数组连续，读一个元素会把邻居一起载入缓存 &gt; 后续访问命中缓存。</li><li>链表节点散落，每次 <code>next</code> 大概率缓存未命中，要去主存取（约 100 周期）。</li><li>3 分：+ 提到&quot;硬件预取器能识别顺序访问，对随机跳转无能为力&quot;。</li><li><strong>命门</strong>：缓存行 + 预取器。</li></ul><p><strong>18. 哈希表的 O(1)</strong></p><ul><li><strong>平均</strong> O(1)，最坏 O(n)（全部冲突）。</li><li>装太满 &gt; 冲突概率上升 &gt; 链表变长 &gt; 查找退化。</li><li>解法：负载因子（0.75）+ 扩容（2 倍）+ 链表转红黑树（Java 8，≥8 个）。</li><li><strong>命门</strong>：&quot;平均&quot;这两个字。</li></ul><p><strong>19. 为什么 B+ 树（四问四答）</strong></p><ul><li><strong>vs 哈希</strong>：不支持范围查询、排序、最左前缀。</li><li><strong>vs 红黑树</strong>：树高 24 层 = 24 次磁盘 IO（每次 10ms）。</li><li><strong>vs B 树</strong>：B 树数据存在所有节点，非叶子能存的键变少，树高更高；且范围查询要在树上反复上下跳。</li><li><strong>B+ 树的优势</strong>：数据全在叶子（非叶子能存更多键 &gt; 树高更低）、叶子有链表（范围查询顺序扫）、每次查询都到叶子（IO 次数稳定）。</li><li><strong>命门</strong>：所有比较都落到&quot;磁盘 IO 次数 = 树高&quot;。</li></ul><p><strong>20. 堆</strong></p><ul><li><strong>为什么用数组</strong>：完全二叉树可以用下标算父子（<code>2i+1</code>、<code>2i+2</code>），不需要指针，缓存友好。</li><li><strong>建堆 O(n)</strong>：从最后一个非叶子节点往前下沉。大部分节点在底层、下沉距离短，总代价是 <code>n/2×0 + n/4×1 + n/8×2 + ...</code> 收敛到 O(n)。</li><li>对比&quot;插入 n 次&quot;是 O(n log n)，因为每个都从底部上浮全程。</li><li><strong>命门</strong>：&quot;越往下节点越多但下沉越少&quot;。</li></ul><p><strong>21. BFS 找无权最短路</strong></p><ul><li>BFS 按层扩展，<strong>第一次到达目标时边数一定最少</strong>（所有更短的都在更早的层）。</li><li>DFS 是&quot;一条路走到黑&quot;，可能先返回一条长路径。</li><li>前提：无权（或边权相同）。有权重必须用 Dijkstra。</li><li><strong>命门</strong>：那个&quot;前提&quot;。</li></ul><p><strong>22. 并查集</strong></p><ul><li>两个优化：<strong>路径压缩</strong>（查找时把路径上所有节点直接挂到根）+ <strong>按秩合并</strong>（矮树挂到高树下）。</li><li>复杂度 O(α(n))，α 是反阿克曼函数，实际 ≤ 4，可视为 O(1)。</li><li><strong>命门</strong>：两个优化都要说，只说一个只能得 1 分。</li></ul><p><strong>23. 快排最坏 O(n²)</strong></p><ul><li>每次 pivot 都是极值，分区极不均衡，递归深度 n。</li><li><strong>什么时候</strong>：数组已排序/逆序 + 固定选首/尾元素当 pivot。</li><li>避免：随机 pivot、三数取中、三路快排、小区间用插入排序。</li><li><strong>命门</strong>：&quot;已排序的数组最慢&quot;这个反直觉结论。</li></ul><h2 id="第四部分-·-数据库" tabindex="-1">第四部分 · 数据库 <a class="header-anchor" href="#第四部分-·-数据库" aria-label="Permalink to &quot;第四部分 · 数据库&quot;">​</a></h2><p><strong>24. B+ 树层数</strong></p><ul><li>非叶子：键 8B + 指针 6B = 14B，一页 16KB &gt; 约 1170 个键。</li><li>叶子：一行约 1KB &gt; 一页约 16 行。</li><li>三层：<code>1170 × 1170 × 16 ≈ 2200 万行</code>。</li><li>所以 2000 万行 = <strong>3 层</strong>，一次查询最多 <strong>3 次 IO</strong>。</li><li><strong>命门</strong>：能写出 1170 这个数是怎么来的。</li></ul><p><strong>25. 回表 / 覆盖索引</strong></p><ul><li><strong>回表</strong>：二级索引叶子只存主键，查到主键后要再去聚簇索引查整行 &gt; 两次 B+ 树查找。</li><li><strong>覆盖索引</strong>：查询的列全在索引里，不用回表。</li><li>例：索引 <code>(name, age)</code>，<code>SELECT name, age WHERE name=&#39;张三&#39;</code> 就覆盖了。</li><li><strong>命门</strong>：能写出一个具体的索引 + SQL 组合。</li></ul><p><strong>26. 最左前缀</strong></p><ul><li><strong>不能</strong>。</li><li>因为索引按 (a,b,c) 排序，<code>a &gt; 1</code> 会命中多个 a 值，b 在每个 a 内部有序但<strong>跨 a 整体无序</strong>，无法用于定位。</li><li>b 只能用于&quot;索引下推&quot;过滤（减少回表），不能缩小扫描范围。</li><li><strong>命门</strong>：&quot;跨 a 整体无序&quot;这个解释。</li></ul><p><strong>27. ACID 实现</strong></p><ul><li>A &gt; undo log（记录旧值，反向操作回滚）</li><li>D &gt; redo log（WAL，先写日志再刷数据页）</li><li>I &gt; 锁 + MVCC</li><li><strong>C 不是数据库实现的</strong>：一致性是业务目标（余额不能为负、总额不变），数据库只提供 A/I/D 这些手段，C 需要应用逻辑 + 约束共同保证。</li><li><strong>命门</strong>：&quot;C 是目标，AID 是手段&quot;。</li></ul><p><strong>28. redo vs binlog + 两阶段提交</strong></p><ul><li>四个区别：层级（引擎层 vs Server 层）、内容（物理 vs 逻辑）、写入（循环写 vs 追加写）、用途（崩溃恢复 vs 主从复制/备份）。</li><li><strong>为什么要两阶段提交</strong>：一次提交要写两个日志，必须保证原子性。先写 redo（prepare）&gt; 写 binlog &gt; redo（commit）。崩溃时看 <strong>binlog 是否完整</strong> 决定提交还是回滚。</li><li><strong>命门</strong>：&quot;用 binlog 的完整性决定 redo 的去留&quot;。</li></ul><p><strong>29. MVCC</strong></p><ul><li>三件套：<strong>隐藏字段</strong>（<code>DB_TRX_ID</code> + <code>DB_ROLL_PTR</code>）、<strong>undo log 版本链</strong>、<strong>ReadView</strong>。</li><li><strong>RC 和 RR 的唯一区别</strong>：ReadView 的生成时机。RC 每次 SELECT 都生成，RR 只在第一次 SELECT 时生成并复用。</li><li>补充：MVCC 只能解决<strong>快照读</strong>的幻读，当前读要靠间隙锁。</li><li><strong>命门</strong>：&quot;只差一处：ReadView 生成时机&quot;。</li></ul><p><strong>30. 慢 SQL 排查</strong></p><ul><li>① 确认真的慢（慢查询日志）</li><li>② EXPLAIN 看 type / key / rows / Extra</li><li>③ 判断&quot;没索引&quot;还是&quot;索引失效&quot;</li><li>④ 看是否返回太多数据（SELECT * / 深分页）</li><li>⑤ 看是否锁等待（长事务）</li><li>⑥ 看数据量（分表 / 归档）</li><li>⑦ 看配置（Buffer Pool、连接数、硬件）</li><li><strong>命门</strong>：不能一上来就说&quot;加索引&quot;。</li></ul><hr><hr><h1 id="自评表" tabindex="-1">自评表 <a class="header-anchor" href="#自评表" aria-label="Permalink to &quot;自评表&quot;">​</a></h1><h2 id="计分" tabindex="-1">计分 <a class="header-anchor" href="#计分" aria-label="Permalink to &quot;计分&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>满分：30 题 × 3 分 = 90 分</span></span>
<span class="line"><span></span></span>
<span class="line"><span>75-90：骨架扎实，可以开始第 2 个月（语言/框架/中间件）</span></span>
<span class="line"><span>60-74：主干有了，把错题所在篇目重读一遍，两周后重考</span></span>
<span class="line"><span>40-59：概念记住了但&quot;为什么&quot;没通，重点补每篇的第 4 节（为什么这么设计）</span></span>
<span class="line"><span>&lt; 40 ：回到导读篇，重新建立模块地图，别急着背细节</span></span></code></pre></div><h2 id="错题记录" tabindex="-1">错题记录 <a class="header-anchor" href="#错题记录" aria-label="Permalink to &quot;错题记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题号</th><th>得分</th><th>属于哪个模块</th><th>错在哪一层</th><th>要重读的篇目</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>&quot;错在哪一层&quot;怎么填</strong>：</p><ul><li>第 1 层（是什么）错 &gt; 没记住，重读一遍即可</li><li>第 2 层（为什么这样设计）错 &gt; 理解不够，重点看&quot;为什么这么设计&quot;和&quot;反事实&quot;</li><li>第 3 层（不这样会怎么坏）错 &gt; 没真懂，回去看&quot;类比失效处&quot;和追问链</li></ul><h2 id="按模块统计" tabindex="-1">按模块统计 <a class="header-anchor" href="#按模块统计" aria-label="Permalink to &quot;按模块统计&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>得分</th><th>满分</th><th>薄弱点</th></tr></thead><tbody><tr><td>操作系统</td><td></td><td>24</td><td></td></tr><tr><td>计算机网络</td><td></td><td>24</td><td></td></tr><tr><td>数据结构</td><td></td><td>21</td><td></td></tr><tr><td>数据库</td><td></td><td>21</td><td></td></tr><tr><td><strong>合计</strong></td><td></td><td><strong>90</strong></td><td></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>得分最低的那个模块，就是你第 2 个月要补的第一块。</span></span>
<span class="line"><span>但更重要的判断是：错在第 2 层还是第 3 层？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 1 层错得多 &gt; 你只是&quot;忘了&quot;，重读就行，不用焦虑</span></span>
<span class="line"><span>第 2/3 层错得多 &gt; 说明当初学的时候就没建立因果，需要重新走一遍&quot;反事实&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>真正危险的是：答对了第 1 层，就以为自己会了。</span></span></code></pre></div><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 闭卷、限时 60 分钟，独立完成 30 题（不翻资料、不查手机）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 按三层标准给自己打分，而不是&quot;大概会&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 填完错题记录表，每道错题都能指出&quot;错在哪一层&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 统计出最薄弱的模块，并列出要重读的 3 篇</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 一周后只重做错题，正确率到 80% 以上</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能说出&quot;这次自测暴露的最大问题是什么&quot;（一句话）</li></ul>`,127)])])}const q=o(i,[["render",r]]);export{c as __pageData,q as default};
